def transform(grid):
    from collections import Counter, defaultdict

    h, w = len(grid), len(grid[0])

    def components(color, rlo=0, rhi=None, clo=0, chi=None):
        if rhi is None:
            rhi = h
        if chi is None:
            chi = w
        seen = set()
        result = []
        for r in range(rlo, rhi):
            for c in range(clo, chi):
                if grid[r][c] != color or (r, c) in seen:
                    continue
                seen.add((r, c))
                q = [(r, c)]
                comp = []
                for y, x in q:
                    comp.append((y, x))
                    for yy, xx in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
                        if (rlo <= yy < rhi and clo <= xx < chi
                                and grid[yy][xx] == color
                                and (yy, xx) not in seen):
                            seen.add((yy, xx))
                            q.append((yy, xx))
                result.append(comp)
        return result

    def bounds(comp):
        return (min(r for r, c in comp), max(r for r, c in comp),
                min(c for r, c in comp), max(c for r, c in comp))

    def shape_key(comp):
        pts0 = [(r - min(y for y, x in comp),
                 c - min(x for y, x in comp)) for r, c in comp]
        forms = []
        for reflection in (1, -1):
            for turns in range(4):
                pts = []
                for y, x in pts0:
                    x *= reflection
                    for _ in range(turns):
                        y, x = x, -y
                    pts.append((y, x))
                my = min(y for y, x in pts)
                mx = min(x for y, x in pts)
                forms.append(tuple(sorted((y-my, x-mx) for y, x in pts)))
        return min(forms)

    # Find the large two-color rectangular template, whose border is its
    # background color.
    candidates = []
    for color in set(v for row in grid for v in row):
        for comp in components(color):
            r0, r1, c0, c1 = bounds(comp)
            rh, rw = r1-r0+1, c1-c0+1
            if rh < 7 or rw < 7:
                continue
            if not all(grid[r0][c] == color and grid[r1][c] == color
                       for c in range(c0, c1+1)):
                continue
            if not all(grid[r][c0] == color and grid[r][c1] == color
                       for r in range(r0, r1+1)):
                continue
            vals = {grid[r][c] for r in range(r0, r1+1)
                    for c in range(c0, c1+1)}
            if len(vals) != 2 or color not in vals:
                continue
            marker = next(v for v in vals if v != color)
            candidates.append((rh*rw, r0, r1, c0, c1, color, marker))

    if not candidates:
        return [row[:] for row in grid]

    _, r0, r1, c0, c1, background, marker = max(candidates)
    rhi, chi = r1 + 1, c1 + 1

    # Learn the color associated with each shape from the scattered examples.
    votes = defaultdict(Counter)
    for color in set(v for row in grid for v in row) - {background, marker}:
        for comp in components(color):
            votes[shape_key(comp)][color] += 1

    out = [grid[r][c0:chi] for r in range(r0, rhi)]
    for comp in components(marker, r0, rhi, c0, chi):
        key = shape_key(comp)
        if key in votes:
            color = votes[key].most_common(1)[0][0]
            for r, c in comp:
                out[r-r0][c-c0] = color

    return out
